import { writeFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

// Import Composio SDK
import { Composio } from '@composio/core';

// Get the directory name
const __dirname = dirname(fileURLToPath(import.meta.url));

async function main() {
  try {
    console.log('Connecting to Composio...');

    // Create Composio client with custom auth configuration
    const composio = new Composio({
      apiKey: process.env.COMPOSIO_API_KEY || ''
    });

    console.log('Creating session for user: zealt-user01');

    // Create session with custom GitHub scopes
    const session = await composio.createSession('zealt-user01', {
      authConfigs: {
        github: {
          scopes: ['repo', 'read:org', 'user']
        }
      }
    });

    console.log('Session created successfully!');
    console.log('Session ID:', session.sessionId);

    // Get session details including auth config
    const sessionDetails = await composio.getSession('zealt-user01');

    console.log('Retrieved session details');

    // Prepare the configuration to save
    const configToSave = {
      userId: 'zealt-user01',
      sessionId: session.sessionId,
      authConfigs: {
        github: {
          scopes: ['repo', 'read:org', 'user']
        }
      },
      createdAt: new Date().toISOString(),
      sessionDetails: sessionDetails
    };

    // Save to JSON file
    const outputPath = '/home/user/session_config.json';
    writeFileSync(outputPath, JSON.stringify(configToSave, null, 2));

    console.log(`Session configuration saved to: ${outputPath}`);
    console.log('Configuration:', JSON.stringify(configToSave, null, 2));

  } catch (error) {
    console.error('Error creating session:', error);
    throw error;
  }
}

// Run the main function
main().catch(error => {
  console.error('Fatal error:', error);
  process.exit(1);
});

