const fs = require('fs');

// Import Composio SDK
const { Composio } = require('@composio/core');

async function main() {
  try {
    console.log('Connecting to Composio...');

    // Create Composio client
    const composio = new Composio({
      apiKey: process.env.COMPOSIO_API_KEY || ''
    });

    console.log('Creating session for user: zealt-user01');

    // Define the custom auth configuration
    const authConfig = {
      github: {
        scopes: ['repo', 'read:org', 'user']
      }
    };

    // Create session with custom GitHub scopes
    const session = await composio.createSession('zealt-user01', {
      authConfigs: authConfig
    });

    console.log('Session created successfully!');

    // Prepare the configuration to save (avoiding circular references)
    const configToSave = {
      userId: 'zealt-user01',
      authConfigs: authConfig,
      createdAt: new Date().toISOString(),
      session: {
        sessionId: session.sessionId || 'created',
        status: 'success'
      }
    };

    // Save to JSON file
    const outputPath = '/home/user/session_config.json';
    fs.writeFileSync(outputPath, JSON.stringify(configToSave, null, 2));

    console.log(`Session configuration saved to: ${outputPath}`);
    console.log('Saved configuration:', JSON.stringify(configToSave, null, 2));

  } catch (error) {
    console.error('Error creating session:', error);
    throw error;
  }
}

// Run the main function
